begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_temp;
select no_plan();
select ok(not has_table_privilege('authenticated','public.workout_movements','UPDATE'),'no broad movement update');
select ok(not has_column_privilege('authenticated','public.workout_movements','slot_snapshot','INSERT'),'derived snapshot is protected');
select ok(not has_column_privilege('authenticated','public.workout_sessions','ad_hoc_focus','UPDATE'),'focus cannot be rewritten');
select ok(not has_function_privilege(r,'public.start_suggested_workout(jsonb,uuid)','EXECUTE'),'no start privilege for '||r) from unnest(array['anon','service_role'])r;
insert into auth.users(id) values(md5('shell_a')::uuid),(md5('shell_b')::uuid);
insert into profiles(id,display_name) values(md5('shell_a')::uuid,'Shell A'),(md5('shell_b')::uuid,'Shell B');
insert into account_preferences(owner_id) values(md5('shell_a')::uuid),(md5('shell_b')::uuid);
set local role authenticated;
select set_config('request.jwt.claims',json_build_object('sub',md5('shell_a')::uuid,'role','authenticated')::text,true);
select set_config('body_test.recipe',(select jsonb_agg(jsonb_build_object('pattern',p.id,'muscle',m.id,'exerciseType','compound','title',p.name) order by p.slug)::text from movement_patterns p cross join muscle_groups m where p.slug in('horizontal_push','incline_push') and m.slug='pectorals'),true);
select set_config('body_test.w',start_suggested_workout(current_setting('body_test.recipe')::jsonb,md5('shell_start')::uuid)::text,true);
select is(start_suggested_workout(current_setting('body_test.recipe')::jsonb,md5('shell_start')::uuid),current_setting('body_test.w')::uuid,'start retries return the same workout');
select is((select count(*)::int from workout_movements where workout_session_id=current_setting('body_test.w')::uuid),2,'one muscle has two persisted intent slots');
select is((select count(*)::int from workout_exercises where workout_session_id=current_setting('body_test.w')::uuid),0,'no actual exercise is preselected');
select is((select source_program_version_id from workout_sessions where id=current_setting('body_test.w')::uuid),null::uuid,'ad-hoc shell does not impersonate a programme');
select ok((select bool_and(slot_snapshot->>'origin'='ad_hoc' and not(slot_snapshot?'exercise_id') and (slot_snapshot->>'target_reps_min')::int=8) from workout_movements where workout_session_id=current_setting('body_test.w')::uuid),'derived intent has defaults, not actuals');
select throws_ok($$select start_suggested_workout('[]'::jsonb,md5('shell_start')::uuid)$$,'23514',null,'changed retry payload rejected');
select set_config('body_test.m',(select id::text from workout_movements where workout_session_id=current_setting('body_test.w')::uuid order by position limit 1),true);
select set_config('body_test.pick',(select id::text from exercises where slug='barbell_bench_press'),true);
select set_config('body_test.e',select_program_exercise(current_setting('body_test.m')::uuid,current_setting('body_test.pick')::uuid,null,md5('shell_selection')::uuid)::text,true);
select is((select count(*)::int from workout_sets where workout_exercise_id=current_setting('body_test.e')::uuid),3,'same logger initializes suggested sets');
select ok((select bool_and(actual_reps is null and actual_weight_kg is null and status='pending' and effort_value is null and not performed_to_failure) from workout_sets where workout_exercise_id=current_setting('body_test.e')::uuid),'suggestions never become actual performance');
select lives_ok($$select log_workout_set(current_setting('body_test.e')::uuid,(select id from workout_sets where workout_exercise_id=current_setting('body_test.e')::uuid order by position limit 1),'save',0,md5('shell_log')::uuid,8,60,'working','external',true)$$,'existing logger records actual performance');
select throws_ok($$select edit_suggested_movement(current_setting('body_test.w')::uuid,md5('shell_remove')::uuid,null,current_setting('body_test.m')::uuid)$$,'P0001',null,'recorded movement cannot be removed');
select throws_ok($$update workout_movements set removed_at=now() where id=current_setting('body_test.m')::uuid$$,'23514',null,'direct removal cannot bypass recorded protection');
select throws_ok($$select edit_suggested_movement(current_setting('body_test.w')::uuid,md5('shell_change')::uuid,current_setting('body_test.recipe')::jsonb->0,current_setting('body_test.m')::uuid)$$,'P0001',null,'changing recorded intent requires confirmation');
select set_config('body_test.new',edit_suggested_movement(current_setting('body_test.w')::uuid,md5('shell_change')::uuid,current_setting('body_test.recipe')::jsonb->0,current_setting('body_test.m')::uuid,true)::text,true);
select ok((select removed_at is null from workout_movements where id=current_setting('body_test.m')::uuid),'confirmed change keeps the original recorded movement');
select is((select count(*)::int from workout_sets where workout_exercise_id=current_setting('body_test.e')::uuid and status='completed' and actual_reps=8 and actual_weight_kg=60),1,'recorded identity and measurements survive');
select is(edit_suggested_movement(current_setting('body_test.w')::uuid,md5('shell_change')::uuid,current_setting('body_test.recipe')::jsonb->0,current_setting('body_test.m')::uuid,true),current_setting('body_test.new')::uuid,'confirmed replacement is idempotent');
select lives_ok($$select edit_suggested_movement(current_setting('body_test.w')::uuid,md5('remove_unstarted')::uuid,null,current_setting('body_test.new')::uuid)$$,'unstarted movement can be removed');
select throws_ok($$select select_program_exercise(current_setting('body_test.new')::uuid,current_setting('body_test.pick')::uuid,null,md5('select_removed')::uuid)$$,'42501',null,'removed intent cannot be selected');
select set_config('request.jwt.claims',json_build_object('sub',md5('shell_b')::uuid,'role','authenticated')::text,true);
select is((select count(*)::int from workout_movements where workout_session_id=current_setting('body_test.w')::uuid),0,'other owner cannot read suggested slots');
select throws_ok($$select edit_suggested_movement(current_setting('body_test.w')::uuid,md5('foreign')::uuid,current_setting('body_test.recipe')::jsonb->0)$$,'42501',null,'other owner cannot add intent');
select set_config('request.jwt.claims',json_build_object('sub',md5('shell_a')::uuid,'role','authenticated')::text,true);
select lives_ok($$select end_workout(current_setting('body_test.w')::uuid,'completed')$$,'partial finish remains available');
select is((select completion_status from workout_sessions where id=current_setting('body_test.w')::uuid),'partial','unselected required movement is not silently completed');
select throws_ok($$select edit_suggested_movement(current_setting('body_test.w')::uuid,md5('closed')::uuid,current_setting('body_test.recipe')::jsonb->0)$$,'23514',null,'closed workout rejects changes');
select throws_ok($$select start_suggested_workout(jsonb_build_array(current_setting('body_test.recipe')::jsonb->0,current_setting('body_test.recipe')::jsonb->0),md5('dupe')::uuid)$$,'22023',null,'duplicate initial pattern/muscle combinations rejected');
select set_config('body_test.four',(current_setting('body_test.recipe')::jsonb||(select jsonb_agg(jsonb_build_object('pattern',p.id,'muscle',m.id,'exerciseType',case when p.slug='elbow_extension' then 'isolation' else 'compound' end,'title',p.name)) from movement_patterns p cross join muscle_groups m where p.slug in('elbow_extension','horizontal_push') and m.slug='triceps'))::text,true);
select set_config('body_test.w4',start_suggested_workout(current_setting('body_test.four')::jsonb,md5('shell_four')::uuid)::text,true);
select is((select count(*)::int from workout_movements where workout_session_id=current_setting('body_test.w4')::uuid),4,'two muscles have four movement slots');
select ok((select bool_and((slot_snapshot->>'target_reps_min')::int=10) from workout_movements where workout_session_id=current_setting('body_test.w4')::uuid and suggested_type='isolation'),'isolation defaults stay distinct');
select lives_ok($$select end_workout(current_setting('body_test.w4')::uuid,'abandoned')$$,'abandon preserves intent without fabricating work');
select set_config('body_test.blank',start_ad_hoc_workout()::text,true);
select is((select count(*)::int from workout_movements where workout_session_id=current_setting('body_test.blank')::uuid),0,'blank workout has no forced suggestions');
reset role;
update workout_sessions set started_at=clock_timestamp()-interval '14 hours',last_activity_at=clock_timestamp()-interval '13 hours',activity_evidence_at=clock_timestamp()-interval '13 hours' where id=current_setting('body_test.blank')::uuid;
set local role authenticated;
select is(edit_suggested_movement(current_setting('body_test.blank')::uuid,md5('expired_add')::uuid,current_setting('body_test.recipe')::jsonb->0),null::uuid,'expired mutation commits cleanup through NULL rejection');
select is((select status from workout_sessions where id=current_setting('body_test.blank')::uuid),'abandoned','expiry never becomes a completed workout');
select is((select count(*)::int from workout_movements where workout_session_id=current_setting('body_test.blank')::uuid),0,'expired mutation creates no movement');
select set_config('body_test.program',start_program_workout((select published_version_id from programs where slug='upper-lower-strength-size'),1,md5('programme_guard')::uuid)::text,true);
select throws_ok($$update workout_movements set removed_at=clock_timestamp() where workout_session_id=current_setting('body_test.program')::uuid$$,'23514',null,'new removal grant cannot remove programme intent');
select is((select count(*)::int from workout_movements where workout_session_id=current_setting('body_test.program')::uuid and removed_at is null),5,'programme movements remain immutable');
select * from finish();rollback;
